SELECT 
    t.*,
    c.customer_name as customerName
FROM customer_transfer t
LEFT JOIN customer c ON t.customer_id = c.customer_id
WHERE 1=1

    AND t.approval_status = #{params.approvalStatus}


    AND t.from_employee_id = #{params.fromEmployeeId}


    AND t.to_employee_id = #{params.toEmployeeId}


    AND t.customer_id = #{params.customerId}


    AND t.transfer_time >= #{params.startDate}


    AND t.transfer_time <= #{params.endDate}

ORDER BY t.transfer_time DESC

SELECT t.*, c.customer_name as customerName FROM customer_transfer t LEFT JOIN customer c ON t.customer_id = c.customer_id WHERE t.approval_status = 'pending'
AND t.to_employee_id = #{params.approverId}
ORDER BY t.transfer_time DESC

SELECT COUNT(*) as totalCount, COUNT(CASE WHEN approval_status = 'pending' THEN 1 END) as pendingCount, COUNT(CASE WHEN approval_status = 'approved' THEN 1 END) as approvedCount, COUNT(CASE WHEN approval_status = 'rejected' THEN 1 END) as rejectedCount, COUNT(CASE WHEN DATE(transfer_time) = CURDATE() THEN 1 END) as todayCount, COUNT(CASE WHEN DATE(transfer_time) >= DATE_SUB(CURDATE(), INTERVAL 7 DAY) THEN 1 END) as weekCount, COUNT(CASE WHEN DATE(transfer_time) >= DATE_SUB(CURDATE(), INTERVAL 30 DAY) THEN 1 END) as monthCount FROM customer_transfer WHERE 1=1
AND transfer_time >= #{params.startDate}
AND transfer_time <= #{params.endDate}
AND (from_employee_id = #{params.employeeId} OR to_employee_id = #{params.employeeId})
